from typing import List

class Solution:

	def __init__(self):
		self.table = None

	def makeChanges(self, N: int, K: int, target: int, coins: List[int]) -> bool:
		if self.table is None:
			self.table = list(([-1] * (target + 1) for k in range(K + 1)))
		if K == 0:
			return target == 0
		if self.table[K][target] != -1:
			return self.table[K][target]
		for c in coins:
			if target - c < 0:
				continue
			if self.makeChanges(N, K - 1, target - c, coins):
				self.table[K][target] = True
				return True
		self.table[K][target] = False
		return False
